import{_ as r,o as a,c as t,ag as i}from"./chunks/framework.BQi7Fipq.js";const s="/cours/assets/exercice3.YRStp9EV.png",o="/cours/assets/exercice3-1.BMTivBCw.png",g=JSON.parse('{"title":"Tableaux, images et légendes","description":"Intégrer des éléments visuels sans nuire à la lisibilité du rapport","frontmatter":{"title":"Tableaux, images et légendes","description":"Intégrer des éléments visuels sans nuire à la lisibilité du rapport"},"headers":[],"relativePath":"modules/03-word/03-tableaux-images.md","filePath":"modules/03-word/03-tableaux-images.md"}'),l={name:"modules/03-word/03-tableaux-images.md"};function u(n,e,d,c,p,m){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="tableaux-images-et-legendes" tabindex="-1">Tableaux, images et légendes <a class="header-anchor" href="#tableaux-images-et-legendes" aria-label="Permalink to &quot;Tableaux, images et légendes&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p>Reprenez le même document et enrichissez-le avec des éléments visuels utiles, comme si vous prépariez une version plus crédible à montrer à quelqu&#39;un.</p><p>À faire dans cette étape :</p><p>En dessous d&#39;un titre de niveau 3:</p><ul><li>Retirer le texte Lorem et :</li><li>ajouter un tableau de 3 colonnes et 5 lignes;</li><li>choisir un style de tableau autre que le style par défaut;</li><li>donner un titre clair au tableau avec une <strong>légende</strong>;</li><li>insérer 2 images liées au sujet choisi;</li><li>utiliser un habillage du texte autour des images;</li><li>ajouter une légende significative sous une des images;</li><li>transformer la source de chaque image en lien cliquable dans la légende.</li></ul><p>Images rapides à télécharger pour l&#39;exercice :</p><ul><li><a href="./images/image-1.jpg">Image 1</a> <a href="https://stocksnap.io/photo/lotus-flower-VC8IOCGVII" target="_blank" rel="noreferrer">https://stocksnap.io/photo/lotus-flower-VC8IOCGVII</a></li><li><a href="./images/image-2.jpg">Image 2</a></li></ul><figure><img src="'+s+'" alt="Exemple de tableau avec légende pour l&#39;exercice 3" class="img-bordered"><figcaption>Exemple de tableau et de légende</figcaption></figure><figure><img src="'+o+'" alt="Exemple d&#39;image avec habillage et légende pour l&#39;exercice 3" class="img-bordered"><figcaption>Exemple d&#39;image avec habillage du texte et légende</figcaption></figure><h2 id="ressources-pour-vous-aider" tabindex="-1">Ressources pour vous aider <a class="header-anchor" href="#ressources-pour-vous-aider" aria-label="Permalink to &quot;Ressources pour vous aider&quot;">​</a></h2><h3 id="habiller-une-image-avec-du-texte-dans-word" tabindex="-1">Habiller une image avec du texte dans Word <a class="header-anchor" href="#habiller-une-image-avec-du-texte-dans-word" aria-label="Permalink to &quot;Habiller une image avec du texte dans Word&quot;">​</a></h3><p>Explique comment positionner une image par rapport au texte. C&#39;est utile pour obtenir une mise en page plus propre que l&#39;insertion brute d&#39;une image au milieu du document. Ça évite le fameux cas où vous brisez votre document Word après avoir inséré une image.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/habiller-une-image-avec-du-texte-dans-word-bdbbe1fe-c089-4b5c-b85c-43997da64a12" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="ajouter-mettre-en-forme-ou-supprimer-des-legendes-dans-word" tabindex="-1">Ajouter, mettre en forme ou supprimer des légendes dans Word <a class="header-anchor" href="#ajouter-mettre-en-forme-ou-supprimer-des-legendes-dans-word" aria-label="Permalink to &quot;Ajouter, mettre en forme ou supprimer des légendes dans Word&quot;">​</a></h3><p>Montre comment nommer correctement une image ou un tableau. C&#39;est important parce qu&#39;une légende claire améliore la compréhension et le professionnalisme du rapport. De plus, une fois la légende ajoutée on peut modifier le texte en ajouter un hyperlien vers la source de l&#39;image/information.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ajouter-mettre-en-forme-ou-supprimer-des-l%C3%A9gendes-dans-word-82fa82a4-f0f3-438f-a422-34bb5cef9c81" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="inserer-un-tableau" tabindex="-1">Insérer un tableau <a class="header-anchor" href="#inserer-un-tableau" aria-label="Permalink to &quot;Insérer un tableau&quot;">​</a></h3><p>Explique comment créer la structure d&#39;un tableau dans Word. C&#39;est la base pour reproduire le tableau exigé dans le modèle.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ins%C3%A9rer-un-tableau-a138f745-73ef-4879-b99a-2f3d38be612a#:~:text=Pour%20un%20tableau%20de%20base,%3E%20Tableau%20%3E%20Ins%C3%A9rer%20un%20tableau." target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="creer-ou-modifier-un-lien-hypertexte" tabindex="-1">Créer ou modifier un lien hypertexte <a class="header-anchor" href="#creer-ou-modifier-un-lien-hypertexte" aria-label="Permalink to &quot;Créer ou modifier un lien hypertexte&quot;">​</a></h3><p>Permet d&#39;ajouter un lien cliquable à du texte. C&#39;est utile pour transformer la source d&#39;une image en lien accessible directement dans la légende.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/cr%C3%A9er-ou-modifier-un-lien-hypertexte-5d8c0804-f998-4143-86b1-1199735e07bf#:~:text=Appuyez%20sur%20Ctrl%2BK.,lien%20dans%20la%20zone%20Adresse." target="_blank" rel="noreferrer">Microsoft Support</a></p>',23)])])}const b=r(l,[["render",u]]);export{g as __pageData,b as default};
